/**
 * How wide a block that holds little is drawn: reduced, which is the cap the stylesheet gives it, or the whole column.
 *
 * Plain ES module with no core/* import, so Node can load it for the headless tests.
 *
 * @module     tiny_studiolms/blocks/block_width
 * @copyright  2026 Jean Lúcio
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

export const WIDTHS = ['reduced', 'full'];

/**
 * Returns the width to draw: the stored one when it is a known value, the block's own default otherwise.
 *
 * The stored value comes from the markup of the page, which anyone can edit, so it is checked before it becomes
 * part of a class name.
 *
 * @param {*} value The width field of the block data.
 * @param {string} fallback What the block did before it had the field.
 * @returns {string} One of WIDTHS.
 */
export const normalizeWidth = (value, fallback) => (WIDTHS.includes(value) ? value : fallback);

/**
 * Builds the flags the width field of a popup reads to select its option.
 *
 * @param {*} value The width field of the block data.
 * @param {string} fallback What the block did before it had the field.
 * @returns {object} widthReduced and widthFull, one of them true.
 */
export const widthVars = (value, fallback) => {
    const width = normalizeWidth(value, fallback);
    return {
        widthReduced: width === 'reduced',
        widthFull: width === 'full',
    };
};

/**
 * Makes the width field of an open popup change the block.
 *
 * @param {HTMLElement} popup The popup node.
 * @param {object} data The block data, changed in place.
 * @param {Function} onUpdate Redraws the block from the data.
 */
export const bindWidth = (popup, data, onUpdate) => {
    popup.querySelector('#pop_block_width')?.addEventListener('input', (ev) => {
        data.width = normalizeWidth(ev.target.value, data.width);
        onUpdate(data);
    });
};
